handlers {
    on_failure {
        notify { channel = "email"; to = vars.owner; message = "失败：${1:...}" }
    }
}

full_workflow.template:
workflow "${1:name}" {
    metadata {
        display_name = "${2:名称}"
        version = "${3:1.0.0}"
    }
    variables {
        ${4:name} = ${5:value}
    }
    trigger { manual {} }
    runtime {
        timeout = 5m
        max_parallel = 2
    }
    steps {
        step ${6:first} {
            action ${7:file.list} {
                ${8}
            }
        }
    }
}

